query NewReleaseRankingPage($limit: Int!, $shouldGetBookmark: Boolean!, $isLoggedIn: Boolean!) {
  legacySearchPPV(
    limit: $limit
    floor: AV
    filter: {legacyReleaseStatus: LATEST_RELEASE}
    sort: SALES_RANK_SCORE
  ) {
    result {
      ...floorTopPPVContentSearchResult
      contents {
        __typename
        actresses {
          id
          name
          __typename
        }
        review {
          average
          count
          __typename
        }
        isInWishList @include(if: $shouldGetBookmark)
        bookmarkCount
        packageImage {
          largeUrl
          __typename
        }
        sampleImages {
          number
          largeUrl
          __typename
        }
        sampleMovie {
          hlsUrl
          mp4Url
          vrUrl
          __typename
        }
        utilizationStatus @include(if: $isLoggedIn)
      }
      __typename
    }
    __typename
  }
}
fragment floorTopPPVContentSearchResult on PPVContentSearchResult {
  contents {
    id
    title
    contentType
    packageImage {
      smallUrl
      mediumUrl
      __typename
    }
    releaseStatus
    isExclusiveDelivery
    salesInfo {
      lowestPrice {
        productId
        price
        discountPrice
        sellingPrice
        legacyProductType
        __typename
      }
      campaign {
        name
        endAt
        discountRate
        __typename
      }
      pointRewardCampaign {
        name
        __typename
      }
      hasMultiplePrices
      __typename
    }
    __typename
  }
  __typename
}
